const start = Date.now();
const startXp = sdk.getSkillXp('Fishing') ?? 0;
let clicks = 0, catches = 0;
while (Date.now() - start < 30000) {
  const state = sdk.getState();
  if (!state) { await sdk.waitForStateUpdate(); continue; }
  if (state.dialog.isOpen) { await sdk.sendClickDialog(0); continue; }
  const spot = state.nearbyNpcs.find(n => /fishing spot/i.test(n.name) && n.optionsWithIndex?.some(o=>/^net$/i.test(o.text)));
  if (spot) {
    const opt = spot.optionsWithIndex.find(o=>/^net$/i.test(o.text));
    await sdk.sendInteractNpc(spot.index, opt.opIndex);
    clicks++;
  }
  await sdk.waitForTicks(2);
}
const endXp = sdk.getSkillXp('Fishing') ?? 0;
console.log('clicks', clicks, 'xpDelta', endXp-startXp, 'rate/min', ((endXp-startXp)/30000*60000)/200);
return { clicks, xpDelta: endXp-startXp };

